      });
    });

    // Messages
    const msgs = [
      { from: 0, to: 1, y: 2.1, label: "up-ado__wit_query(id: 123)", color: C.accent2 },
      { from: 1, to: 1, y: 2.6, label: "decrypt user's sealed creds", color: C.muted },
