      { from: 1, to: 1, y: 3.8, label: "log usage (tool, tokens, latency)", color: C.muted },
      { from: 1, to: 0, y: 4.2, label: "result", color: C.accent4 },
    ];

    msgs.forEach(m => {
      const x1 = actors[m.from].x + 0.1;
      const x2 = actors[m.to].x + 0.1;
      if (m.from === m.to) {
        // Self-call: small loop
        s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
          x: x1 + 0.15, y: m.y - 0.05, w: 2.6, h: 0.35, fill: { color: C.bgLight }, rectRadius: 0.05,
