          fontSize: 10, fontFace: "Calibri", italic: true, color: m.color, margin: 0,
        });
      } else {
        // Arrow
        const leftX = Math.min(x1, x2);
        const w = Math.abs(x2 - x1);
        s.addShape(pres.shapes.LINE, {
          x: leftX, y: m.y + 0.1, w, h: 0,
          line: { color: m.color, width: 2 },
