          fontSize: 10, fontFace: "Courier New", color: m.color, align: "center", margin: 0,
        });
      }
    });

    s.addNotes("The agent calls up-ado__wit_query → ctxlayer decrypts the user's sealed credentials → proxies the native wit_query call to ADO → ADO returns the result → ctxlayer logs usage (tool, tokens, latency) → returns the result to the agent. The agent never sees credentials.");
