    });
    const practSteps = [
      { text: "Go to yukitools.dev → sign in", options: { bullet: { type: "number" }, breakLine: true, fontSize: 13, color: C.text } },
      { text: "/app/upstreams → connect services", options: { bullet: { type: "number" }, breakLine: true, fontSize: 13, color: C.text } },
