const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaDatabase, FaPlug, FaBook, FaShieldAlt, FaSearch, FaGitAlt, FaUsers, FaChartBar, FaLock, FaCog, FaRocket, FaKey, FaExclamationTriangle, FaCheckCircle, FaArrowRight, FaCode, FaFileAlt, FaTags, FaFolderOpen, FaLink, FaEye, FaTools, FaLightbulb, FaQuestion } = require("react-icons/fa");

// ── Palette ──
const C = {
  bg:       "0F172A",  // deep navy
  bgLight:  "1E293B",  // card background
  bgMid:    "334155",  // slightly lighter for contrast
  accent:   "F97316",  // orange
  accent2:  "06B6D4",  // cyan
  accent3:  "8B5CF6",  // purple
  accent4:  "10B981",  // green
  text:     "F8FAFC",  // near-white
  muted:    "94A3B8",  // gray
  dim:      "64748B",  // dimmer gray
  white:    "FFFFFF",
  red:      "EF4444",
  tableHead:"1E3A5F",
  tableRow1:"0F172A",
  tableRow2:"1A2744",
};

// ── Icon helper ──
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToBase64Png(IconComponent, color = "#FFFFFF", size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ── Shadow factory ──
const mkShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 45, opacity: 0.25 });

async function build() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Steven Noels";
  pres.title = "ctxlayer — Workshop";

  // Pre-render icons
  const icons = {
    database: await iconToBase64Png(FaDatabase, "#06B6D4"),
    plug:     await iconToBase64Png(FaPlug, "#F97316"),
    book:     await iconToBase64Png(FaBook, "#8B5CF6"),
    shield:   await iconToBase64Png(FaShieldAlt, "#10B981"),
    search:   await iconToBase64Png(FaSearch, "#06B6D4"),
    git:      await iconToBase64Png(FaGitAlt, "#F97316"),
    users:    await iconToBase64Png(FaUsers, "#94A3B8"),
    chart:    await iconToBase64Png(FaChartBar, "#10B981"),
    lock:     await iconToBase64Png(FaLock, "#EF4444"),
    cog:      await iconToBase64Png(FaCog, "#94A3B8"),
    rocket:   await iconToBase64Png(FaRocket, "#F97316"),
    key:      await iconToBase64Png(FaKey, "#F97316"),
    warning:  await iconToBase64Png(FaExclamationTriangle, "#EF4444"),
    check:    await iconToBase64Png(FaCheckCircle, "#10B981"),
    arrow:    await iconToBase64Png(FaArrowRight, "#F97316"),
    code:     await iconToBase64Png(FaCode, "#06B6D4"),
    file:     await iconToBase64Png(FaFileAlt, "#94A3B8"),
    tags:     await iconToBase64Png(FaTags, "#8B5CF6"),
    folder:   await iconToBase64Png(FaFolderOpen, "#F97316"),
    link:     await iconToBase64Png(FaLink, "#06B6D4"),
    eye:      await iconToBase64Png(FaEye, "#10B981"),
    tools:    await iconToBase64Png(FaTools, "#F97316"),
    lightbulb:await iconToBase64Png(FaLightbulb, "#F97316"),
    question: await iconToBase64Png(FaQuestion, "#94A3B8"),
    checkW:   await iconToBase64Png(FaCheckCircle, "#FFFFFF"),
    warningW: await iconToBase64Png(FaExclamationTriangle, "#FFFFFF"),
    plugW:    await iconToBase64Png(FaPlug, "#FFFFFF"),
    bookW:    await iconToBase64Png(FaBook, "#FFFFFF"),
    shieldW:  await iconToBase64Png(FaShieldAlt, "#FFFFFF"),
    databaseW:await iconToBase64Png(FaDatabase, "#FFFFFF"),
  };

  // ════════════════════════════════════════
  // SLIDE 1 — Title
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    // Large title
    s.addText("ctxlayer", {
      x: 0.8, y: 1.2, w: 8.4, h: 1.2,
      fontSize: 56, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });
    s.addText("Your team's shared context layer", {
      x: 0.8, y: 2.3, w: 8.4, h: 0.6,
      fontSize: 24, fontFace: "Calibri", color: C.accent, margin: 0,
    });
    s.addText("yukitools.dev  ·  Workshop", {
      x: 0.8, y: 3.2, w: 8.4, h: 0.5,
      fontSize: 16, fontFace: "Calibri", color: C.muted, margin: 0,
    });
    // Four small icons bottom right
    s.addImage({ data: icons.database, x: 6.5, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.plug, x: 7.2, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.book, x: 7.9, y: 4.2, w: 0.5, h: 0.5 });
    s.addImage({ data: icons.shield, x: 8.6, y: 4.2, w: 0.5, h: 0.5 });
    s.addNotes("Welcome to the ctxlayer workshop. This presentation covers the main concepts of ctxlayer and how to use it as a practitioner or admin on the yukitools.dev deployment.");
  }

  // ════════════════════════════════════════
  // SLIDE 2 — The problem: individual connections
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("The MCP landscape today", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });
    s.addText("Every developer manages their own connections", {
      x: 0.8, y: 0.95, w: 8.4, h: 0.4,
      fontSize: 16, fontFace: "Calibri", color: C.accent, margin: 0,
    });

    // Diagram: 4 users on the left, 4 services on the right, chaotic lines between them
    const userNames = ["Alice", "Bob", "Carol", "Dave"];
    const serviceNames = ["ADO", "Notion", "Driver", "Yuki IA"];
    const userX = 1.0, serviceX = 7.5;
    const startY = 1.7, gap = 0.85;

    // User boxes
    for (let i = 0; i < 4; i++) {
      const y = startY + i * gap;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: userX, y, w: 1.5, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08, shadow: mkShadow(),
      });
      s.addText(userNames[i], {
        x: userX, y, w: 1.5, h: 0.55,
        fontSize: 13, fontFace: "Calibri", color: C.text, align: "center", valign: "middle", margin: 0,
      });
    }

    // Service boxes
    for (let i = 0; i < 4; i++) {
      const y = startY + i * gap;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: serviceX, y, w: 1.5, h: 0.55, fill: { color: C.bgLight }, rectRadius: 0.08, shadow: mkShadow(),
      });
      s.addText(serviceNames[i], {
        x: serviceX, y, w: 1.5, h: 0.55,
        fontSize: 13, fontFace: "Calibri", color: C.accent, align: "center", valign: "middle", margin: 0,
      });
    }

    // Chaotic lines — each user connects to multiple services
    const connections = [
      [0,0],[0,1],[0,2],[0,3],
      [1,0],[1,1],[1,3],
      [2,0],[2,2],[2,3],
      [3,0],[3,1],[3,2],
    ];
    const lineColors = [C.red, C.accent, C.accent2, C.accent3, C.accent4, C.muted];
    connections.forEach((conn, idx) => {
      const y1 = startY + conn[0] * gap + 0.275;
      const y2 = startY + conn[1] * gap + 0.275;
      const x1 = userX + 1.5;
      const x2 = serviceX;
      // Draw angled line using LINE shape
      s.addShape(pres.shapes.LINE, {
        x: x1, y: Math.min(y1, y2), w: x2 - x1, h: Math.abs(y2 - y1) * (y2 >= y1 ? 1 : 1),
        line: { color: lineColors[idx % lineColors.length], width: 1.2, dashType: "dash" },
        flipV: y2 < y1,
      });
    });

    // "N×M" label
    s.addText("4 users × 4 services = 16 connections", {
      x: 2.8, y: 4.6, w: 4.4, h: 0.4,
      fontSize: 14, fontFace: "Calibri", color: C.red, align: "center", margin: 0, bold: true,
    });

    s.addNotes("Each person has to configure MCP servers locally — claude_desktop_config.json, .mcp.json, managed-mcp.json. Credentials live in local files. No shared knowledge. No visibility into tool usage. Onboarding = 'copy my config and change the tokens'.");
  }

  // ════════════════════════════════════════
  // SLIDE 3 — What goes wrong
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("What goes wrong", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    const problems = [
      { icon: icons.key, title: "Token rotation", desc: "Everyone has to update their local config" },
      { icon: icons.warning, title: "New upstream", desc: "Someone Slacks the setup — half the team misses it" },
      { icon: icons.search, title: "No org context", desc: "Agent asks 'which ADO project?' every single time" },
      { icon: icons.lock, title: "No guardrails", desc: "Any tool is callable, no conventions enforced" },
      { icon: icons.eye, title: "Zero visibility", desc: "Are people using the Notion integration? No idea" },
    ];

    problems.forEach((p, i) => {
      const y = 1.3 + i * 0.82;
      s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
        x: 1.0, y, w: 8.0, h: 0.65, fill: { color: C.bgLight }, rectRadius: 0.08,
      });
      s.addImage({ data: p.icon, x: 1.2, y: y + 0.1, w: 0.42, h: 0.42 });
      s.addText(p.title, {
        x: 1.8, y, w: 2.2, h: 0.65,
        fontSize: 14, fontFace: "Calibri", bold: true, color: C.text, valign: "middle", margin: 0,
      });
      s.addText(p.desc, {
        x: 4.0, y, w: 4.8, h: 0.65,
        fontSize: 13, fontFace: "Calibri", color: C.muted, valign: "middle", margin: 0,
      });
    });

    s.addNotes("These pain points compound at scale. Token rotation becomes a fire drill. New services are adopted unevenly. The agent has no memory of your org's conventions.");
  }

  // ════════════════════════════════════════
  // SLIDE 4 — The solution: hub and spoke
  // ════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.bg };
    s.addText("One connection, full context", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.7,
      fontSize: 36, fontFace: "Calibri", bold: true, color: C.text, margin: 0,
    });

    // Hub: ctxlayer in the center
